import itertools

def find_bibd(n, k):
    edges = list(itertools.combinations(range(n), 2))
    triangles = list(itertools.combinations(range(n), 3))

    # This is a small enough problem to solve with a simple search or just check existence.
    # Let's use a simple backtracking search.

    # Edge counts
    edge_counts = {edge: 0 for edge in edges}

    def solve(tri_idx, current_T):
        if len(current_T) == k * n * (n - 1) // 6:
            # Check if all edges have count k
            if all(edge_counts[e] == k for e in edges):
                return current_T
            return None

        if tri_idx == len(triangles):
            return None

        # Try including triangle tri_idx
        tri = triangles[tri_idx]
        tri_edges = list(itertools.combinations(tri, 2))

        # Check if we can include it
        if all(edge_counts[e] < k for e in tri_edges):
            for e in tri_edges:
                edge_counts[e] += 1
            res = solve(tri_idx + 1, current_T + [tri])
            if res: return res
            for e in tri_edges:
                edge_counts[e] -= 1

        # Try excluding it
        res = solve(tri_idx + 1, current_T)
        if res: return res

        return None

    return solve(0, [])

print(find_bibd(6, 2))
